package nl.nielsnotsmurf.cleanui.logic

import nl.nielsnotsmurf.cleanui.model.OneRepMax
import org.json.JSONObject
import kotlin.math.abs

/**
 * Maps every loadable exercise to one of the 1RM-test anchors with a ratio
 * (incline bench = 0.9 × bench), so one tested 1RM gives estimates for the whole library.
 * The table lives in assets/one_rep_max_map.json, generated by clean-ui/scripts/generate_one_rep_max_map.py.
 */
class OneRepMaxMap(private val entries: Map<String, Entry>) {

    data class Entry(val anchorId: String, val ratio: Float)

    private val anchorIds = entries.values.mapTo(HashSet()) { it.anchorId }

    /** Anchor and ratio for [exerciseId]; an anchor maps to itself at 1.0. */
    fun entryFor(exerciseId: String): Entry? =
        entries[exerciseId] ?: Entry(exerciseId, 1f).takeIf { exerciseId in anchorIds }

    /**
     * Estimated 1RM for [exerciseId] from the lifter's [known] 1RMs (exerciseId -> 1RM).
     * Only real 1RMs (tested, typed in, or from history) count, never other estimates.
     * The anchor itself is preferred; otherwise the related lift whose ratio is closest to the anchor's.
     */
    fun estimate(exerciseId: String, known: Map<String, OneRepMax>): Float? {
        val target = entryFor(exerciseId) ?: return null
        val anchorKg = known.mapNotNull { (id, orm) ->
            if (id == exerciseId || orm.isEstimate || orm.kg <= 0f) return@mapNotNull null
            val e = entryFor(id)?.takeIf { it.anchorId == target.anchorId } ?: return@mapNotNull null
            e.ratio to orm.kg / e.ratio
        }.minByOrNull { abs(it.first - 1f) }?.second ?: return null
        return LoadCalculator.roundToStep(anchorKg * target.ratio).takeIf { it > 0f }
    }

    companion object {
        const val ASSET = "one_rep_max_map.json"

        fun parse(json: String): OneRepMaxMap {
            val exercises = JSONObject(json).getJSONObject("exercises")
            val entries = exercises.keys().asSequence().associateWith { id ->
                val e = exercises.getJSONObject(id)
                Entry(e.getString("anchor"), e.getDouble("ratio").toFloat())
            }
            return OneRepMaxMap(entries)
        }

        val EMPTY = OneRepMaxMap(emptyMap())
    }
}
